<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createSchedule, deleteSchedule, getSchedulePage, updateSchedule, type AdminSchedule } from '@/api/schedule'
const rows=ref<AdminSchedule[]>([]);const total=ref(0);const loading=ref(false);const dialog=ref(false);const editing=ref<number|null>(null);const query=reactive({page:1,pageSize:10,type:undefined as string|undefined});const form=reactive({title:'',targetTime:'',type:'countdown'})
async function load(){loading.value=true;try{const r=await getSchedulePage(query);rows.value=r.records||[];total.value=r.total||0}finally{loading.value=false}}
function open(raw?:unknown){const row=raw as AdminSchedule|undefined;editing.value=row?.id||null;Object.assign(form,row||{title:'',targetTime:'',type:'countdown'});dialog.value=true}
async function save(){if(editing.value===null)await createSchedule(form);else await updateSchedule(editing.value,form);dialog.value=false;ElMessage.success('保存成功');load()}
async function remove(raw:unknown){const row=raw as AdminSchedule;await ElMessageBox.confirm('确定删除该日程吗？','提示',{type:'warning'});await deleteSchedule(row.id);load()};onMounted(load)
</script>
<template><div class="page"><el-card shadow="never"><template #header><div class="header"><span>日程管理</span><el-button type="primary" @click="open">新增日程</el-button></div></template><el-form :inline="true"><el-form-item label="类型"><el-select v-model="query.type" clearable><el-option label="倒计时" value="countdown"/><el-option label="日程" value="schedule"/></el-select></el-form-item><el-button @click="load">查询</el-button></el-form><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="id" label="ID"/><el-table-column prop="title" label="标题"/><el-table-column prop="targetTime" label="目标时间"/><el-table-column prop="type" label="类型"/><el-table-column label="操作"><template #default="s"><el-button link @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" layout="total,prev,pager,next" @current-change="load"/></el-card><el-dialog v-model="dialog" :title="editing===null?'新增日程':'编辑日程'"><el-form><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="目标时间"><el-input v-model="form.targetTime" placeholder="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-form-item label="类型"><el-select v-model="form.type"><el-option label="倒计时" value="countdown"/><el-option label="日程" value="schedule"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template><style scoped>.page{padding:16px}.header{display:flex;justify-content:space-between}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
